import sys
if sys.version_info[0] >= 3:
    def py3_unicode(x):
        """
        In python3 converts bytes to string if needed. This method should be used in every place when being uncertain of type of output
        :param x:
        :return:
        """
        if isinstance(x, bytes):
            return x.decode('utf-8')
        else:
            return x
else:
    def py3_unicode(x):
        """
        In python2 no conversion will be done cause string is always represented by str class
        :param x:
        :return:
        """
        if isinstance(x, unicode) or x is None:
            return x
        else:
            return unicode(x, 'utf-8')
